from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_treatment_objects import Xvi_Treatment_page
from ..interactions import new_treatment_reg

def enter_treatment_details(treatmentID: str, treatmentDescription: str ,treatmentOrientation:str) -> None:
    """Enter all basic details on the New treatment window
    treatmentID,treatmentDescription,treatmentOrientation
    """
    new_treatment_reg.open_treatment_newPage()
    new_treatment_reg.typeText_in_treatement_id(treatmentID)
    new_treatment_reg.typeText_in_treatement_description(treatmentDescription)
    new_treatment_reg.select_orientation(treatmentOrientation)
    new_treatment_reg.select_inactive()
    new_treatment_reg.clickOK()